SELECT branch_id
  FROM branch
 WHERE company_id = #{companyId}
   AND branch_id = #{branchId}
   FOR UPDATE

SELECT use_yn
  FROM branch
 WHERE company_id = #{companyId}
   AND branch_id = #{branchId}





SELECT COUNT(*)
  FROM branch b
  JOIN it_ticket t ON t.company_id = b.company_id
                  AND t.branch_id = b.branch_id
 WHERE b.company_id = #{companyId}
   AND b.branch_id = #{branchId}
   AND t.ticket_type = #{equipment}
   AND t.status_code IN (#{received}, #{assigned}, #{inProgress})

