UPDATE branch
   SET use_yn = 'N',
       updated_at = CAST(SYSTIMESTAMP AT TIME ZONE 'Asia/Seoul' AS TIMESTAMP)
 WHERE company_id = #{companyId}
   AND branch_id = #{branchId}
   AND use_yn = 'Y'
